<?php

namespace App\Services\Coach;

use App\Models\Exercise;
use Illuminate\Support\Facades\Log;

/**
 * Phase 11C — deterministic validation of structured training plans.
 * LLM output is never trusted here; plans are generated by application code and still validated.
 */
class TrainingPlanValidator
{
    public function __construct(
        private readonly CoachExerciseRetrievalService $exerciseRetrieval,
    ) {}

    /**
     * @param  array<string, mixed>  $plan
     * @return array{ok: bool, plan: array<string, mixed>|null, errors: list<string>}
     */
    public function validate(array $plan): array
    {
        $errors = [];

        if (($plan['schema_version'] ?? null) !== '11c.1') {
            $errors[] = 'invalid_schema_version';
        }

        $sessions = $plan['sessions'] ?? null;
        if (! is_array($sessions) || $sessions === []) {
            $errors[] = 'sessions_empty';

            return ['ok' => false, 'plan' => null, 'errors' => $errors];
        }

        $allIds = [];
        foreach ($sessions as $sIndex => $session) {
            if (! is_array($session)) {
                $errors[] = "session_{$sIndex}_invalid";

                continue;
            }
            $exercises = $session['exercises'] ?? [];
            if (! is_array($exercises) || $exercises === []) {
                $errors[] = "session_{$sIndex}_empty";

                continue;
            }

            $sessionSeen = [];
            foreach ($exercises as $eIndex => $exercise) {
                if (! is_array($exercise)) {
                    $errors[] = "session_{$sIndex}_exercise_{$eIndex}_invalid";

                    continue;
                }

                $id = $exercise['exercise_id'] ?? null;
                if (! is_numeric($id) || (int) $id <= 0) {
                    $errors[] = "session_{$sIndex}_exercise_{$eIndex}_bad_id";

                    continue;
                }
                $id = (int) $id;
                $allIds[] = $id;

                if (isset($sessionSeen[$id])) {
                    $errors[] = "session_{$sIndex}_duplicate_exercise_{$id}";
                }
                $sessionSeen[$id] = true;

                if (! ($exercise['grounded'] ?? false)) {
                    $errors[] = "session_{$sIndex}_exercise_{$id}_not_grounded";
                }

                $sets = $exercise['sets'] ?? null;
                if (! is_numeric($sets) || (int) $sets <= 0) {
                    $errors[] = "session_{$sIndex}_exercise_{$id}_bad_sets";
                }

                $hasReps = isset($exercise['reps_min'], $exercise['reps_max'])
                    && is_numeric($exercise['reps_min'])
                    && is_numeric($exercise['reps_max'])
                    && (int) $exercise['reps_min'] > 0
                    && (int) $exercise['reps_max'] >= (int) $exercise['reps_min'];
                $hasDuration = isset($exercise['duration_seconds']) && is_numeric($exercise['duration_seconds']) && (int) $exercise['duration_seconds'] > 0;
                $hasRounds = isset($exercise['rounds']) && is_numeric($exercise['rounds']) && (int) $exercise['rounds'] > 0;

                if (! $hasReps && ! $hasDuration && ! $hasRounds) {
                    $errors[] = "session_{$sIndex}_exercise_{$id}_bad_prescription";
                }

                // Nonsensical combo: long duration AND high fixed reps without rounds — reject.
                if ($hasDuration && $hasReps && (int) $exercise['duration_seconds'] >= 600 && (int) $exercise['reps_max'] >= 8 && ! $hasRounds) {
                    $errors[] = "session_{$sIndex}_exercise_{$id}_nonsensical_duration_reps";
                }

                $rest = $exercise['rest_seconds'] ?? null;
                if ($rest !== null && (! is_numeric($rest) || (int) $rest < 0 || (int) $rest > 600)) {
                    $errors[] = "session_{$sIndex}_exercise_{$id}_bad_rest";
                }
            }
        }

        // Batch-validate all IDs against OCTA FIT active catalog.
        $uniqueIds = array_values(array_unique($allIds));
        $validated = $this->exerciseRetrieval->validateIds($uniqueIds, 'en');
        if ($validated['rejected'] !== []) {
            foreach ($validated['rejected'] as $rej) {
                $errors[] = 'ungrounded_exercise_'.$rej['id'];
                Log::debug('coach.training_plan.rejected_exercise', $rej);
            }
        }

        // Ensure every plan exercise is still active in DB (defense in depth).
        if ($uniqueIds !== []) {
            $activeCount = Exercise::query()->active()->whereIn('id', $uniqueIds)->count();
            if ($activeCount !== count($uniqueIds)) {
                $errors[] = 'inactive_or_missing_exercises';
            }
        }

        if ($errors !== []) {
            return ['ok' => false, 'plan' => null, 'errors' => $errors];
        }

        $plan['validated'] = true;

        return ['ok' => true, 'plan' => $plan, 'errors' => []];
    }

    /**
     * Inject invalid IDs into a plan copy then validate — used by tests.
     *
     * @param  array<string, mixed>  $plan
     * @param  list<int>  $fakeIds
     * @return array{ok: bool, errors: list<string>}
     */
    public function validateWithInjectedIds(array $plan, array $fakeIds): array
    {
        if (! isset($plan['sessions'][0]['exercises'][0])) {
            return ['ok' => false, 'errors' => ['no_exercise_to_inject']];
        }
        foreach ($fakeIds as $fakeId) {
            $plan['sessions'][0]['exercises'][0]['exercise_id'] = $fakeId;
            $plan['sessions'][0]['exercises'][0]['grounded'] = true;
        }

        $result = $this->validate($plan);

        return ['ok' => $result['ok'], 'errors' => $result['errors']];
    }
}
